CREATE TABLE IF NOT EXISTS races (race_key TEXT PRIMARY KEY,race_date TEXT NOT NULL,course TEXT NOT NULL,meeting_no TEXT,day_no INTEGER,race_no INTEGER,surface TEXT,distance INTEGER,track_condition TEXT,weather TEXT,field_size INTEGER,class_name TEXT,pace_index REAL,track_bias_score REAL);
CREATE TABLE IF NOT EXISTS runners (race_key TEXT NOT NULL,post INTEGER,bracket INTEGER,horse TEXT NOT NULL,sex TEXT,age INTEGER,weight_carried REAL,jockey TEXT,trainer TEXT,horse_weight REAL,horse_weight_diff REAL,finish INTEGER,odds REAL,popularity INTEGER,time TEXT,margin TEXT,early_position REAL,final_position REAL,last3f REAL,sire TEXT,dam_sire TEXT,running_style TEXT,model_win_prob REAL,fair_odds REAL,expected_value REAL,value_edge REAL,win INTEGER,horse_win_rate REAL,jockey_win_rate REAL,trainer_win_rate REAL,course_win_rate REAL,distance_win_rate REAL,surface_win_rate REAL,condition_win_rate REAL,course_distance_win_rate REAL,last_finish REAL,last3_avg_finish REAL,days_since_last REAL,field_size INTEGER,post_pct REAL,bracket_pct REAL,market_prob REAL,track_bias_score REAL,pace_score REAL,PRIMARY KEY(race_key,post),FOREIGN KEY(race_key) REFERENCES races(race_key));
CREATE INDEX IF NOT EXISTS idx_runners_horse ON runners(horse);
CREATE INDEX IF NOT EXISTS idx_races_date ON races(race_date);
CREATE INDEX IF NOT EXISTS idx_races_course ON races(course,surface,distance);
